package com.aadil.ecommerce.security;import com.aadil.ecommerce.UserRole;import com.aadil.ecommerce.responses.UserLoginResponse;import io.jsonwebtoken.Claims;import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import jakarta.annotation.PostConstruct;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.stereotype.Component;import javax.crypto.SecretKey;import java.util.Base64;import java.util.Date;import java.util.function.Function;@Componentpublic class JwtUtility {    @Value("${jwt.secret}")    private String secret;    @Value("${jwt.expiration}")    private Long expiration;    SecretKey secretKey;    @PostConstruct    protected void runFirst(){        byte[] byteCode = Base64.getDecoder().decode(secret);        this.secretKey = Keys.hmacShaKeyFor(byteCode);    }    public String generateToken (UserDetails userDetails){        return Jwts.builder().signWith(secretKey).                subject(userDetails.getUsername()).                expiration(new Date(System.currentTimeMillis()+expiration)).claim("role",userDetails.getAuthorities().iterator().next().getAuthority()).compact();    }    public Claims parseClaims (String token){        return Jwts.parser().verifyWith(secretKey).build().parseSignedClaims(token).getPayload();    }    public String extractUsername(String token){        return parseClaims(token).getSubject();    }    public boolean isTokenValid (String token, UserDetails userDetails){        String username = extractUsername(token);        return username.equals(userDetails.getUsername()) && !isExpired(token);    }    private boolean isExpired(String token) {        return parseClaims(token).getExpiration().before(new Date(expiration));    }}